		if _serdeErr != nil {
			w.out.err = _serdeErr
		}
	}()
	s, e := w.Seq(len(v))
	if e != nil {
		return e
	}
	for _, b := range v {
		if e = s.Element(func(s serde.Serializer) error { return s.Uint64(uint64(b)) }); e != nil {
			return e
		}
	}
	return s.End()
}

type container struct {
	w                   *writer
	size, n             int
	object, ended, busy bool
	mapKeys             bool
	variant             bool
	seen                map[string]bool
}

func (w *writer) begin(n int, obj bool) (_serdeResult0 *container, _serdeErr error) {
	defer func() {
		if _serdeErr != nil {
			w.out.err = _serdeErr
		}
	}()
	if n < -1 {
		return nil, fail("State", "invalid length hint")
	}
	if e := w.start(); e != nil {
		return nil, e
	}
	s := "["
	if obj {
		s = "{"
	}
	if e := w.out.put(s); e != nil {
		return nil, e
	}
	return &container{w: w, size: n, object: obj, seen: map[string]bool{}}, nil
}
func (w *writer) Seq(n int) (serde.SeqWriter, error) { return w.begin(n, false) }
func (w *writer) Map(n int) (serde.MapWriter, error) {
	c, e := w.begin(n, true)
	if e == nil {
		c.mapKeys = true
	}
	return c, e
}
func (w *writer) Struct(_ string, n int) (_serdeResult0 serde.StructWriter, _serdeErr error) {
	defer func() {
		if _serdeErr != nil {
			w.out.err = _serdeErr
		}
	}()
	return w.begin(n, true)
}
func (c *container) next() (_serdeErr error) {
	defer func() {
		if _serdeErr != nil {
			c.w.out.err = _serdeErr
		}
	}()
	if c.busy {
		return fail("State", "reentrant container access")
	}
	if c.ended {
		return fail("State", "container already ended")
	}
	if c.size >= 0 && c.n >= c.size {
		return fail("State", "too many container entries")
	}
	if c.n > 0 {
		if e := c.w.out.put(","); e != nil {
			return e
		}
	}
	c.n++
	return nil
}
func (c *container) Element(f serde.WriteValue) (_serdeErr error) {
	defer func() {
		if _serdeErr != nil {
			c.w.out.err = _serdeErr
		}
	}()
	if e := c.next(); e != nil {
		return e
	}
	c.busy = true
	defer func() { c.busy = false }()
	return serde.AtIndex(c.w.child(f), c.n-1)
}
func (c *container) Field(k string, f serde.WriteValue) (_serdeErr error) {
	defer func() {
		if _serdeErr != nil {
			c.w.out.err = _serdeErr
		}
	}()
	if c.seen[k] {
		return fail("Duplicate", "duplicate object key: "+k)
	}
	s, e := quote(k)
	if e != nil {
		return e
	}
	if e = c.next(); e != nil {
		return e
	}
	c.seen[k] = true
	if e = c.w.out.put(s + ":"); e != nil {
		return e
	}
	c.busy = true
	defer func() { c.busy = false }()
	err := c.w.child(f)
	if c.variant {
		return serde.AtVariant(err, k)
	}
	if c.mapKeys {
		return serde.AtMapKey(err, k)
	}
	return serde.AtField(err, k)
}
func (c *container) Entry(k, v serde.WriteValue) (_serdeErr error) {
	defer func() {
		if _serdeErr != nil {
			c.w.out.err = _serdeErr
		}
	}()
	b, e := Encode(k)
	if e != nil {
		return e
	}
	var s string
	if len(b) == 0 || b[0] != '"' {
		return fail("Type", "JSON map keys must be strings")
	}
	if e = json.Unmarshal(b, &s); e != nil {
		return e
	}
	return c.Field(s, v)
}
func (c *container) End() (_serdeErr error) {
	defer func() {
		if _serdeErr != nil {
			c.w.out.err = _serdeErr
		}
	}()
	if c.busy {
		return fail("State", "reentrant container access")
	}
	if c.ended {
		return fail("State", "container already ended")
	}
	c.ended = true
	if c.size >= 0 && c.n != c.size {
		return fail("State", "container length does not match hint")
	}
	s := "]"
	if c.object {
		s = "}"
	}
	e := c.w.out.put(s)
	c.w.done = e == nil
	return e
}
func (w *writer) UnitVariant(_, v string) (_serdeErr error) {
	defer func() {
		if _serdeErr != nil {
			w.out.err = _serdeErr
		}
	}()
	return w.String(v)
}
func (w *writer) NewtypeVariant(_, v string, f serde.WriteValue) (_serdeErr error) {
	defer func() {
		if _serdeErr != nil {
			w.out.err = _serdeErr
		}
	}()
	c, e := w.begin(1, true)
	if e == nil {
		c.variant = true
	}
	if e != nil {
		return e
	}
	if e = c.Field(v, f); e != nil {
		return e
	}
	return c.End()
}

package serde_macros

import (
	"fmt"
	"strconv"
	"strings"

	pm "github.com/goxide-lang/syntax/proc_macro"
	"github.com/goxide-lang/syntax/syn"
	"github.com/goxide-lang/syntax/token"
)

func serdeFragment(ctx pm.Context, source string) token.TokenStream {
	stream, err := token.ParseText(source, ctx.DefSite())
	if err != nil {
		panic(err)
	}
	nodes := stream.Tokens()
	for len(nodes) > 0 && nodes[len(nodes)-1].Kind() == token.SemicolonKind {
		nodes = nodes[:len(nodes)-1]
	}
	return token.New(nodes...)
}
func serdeGroup(ctx pm.Context, delimiter token.Delimiter, stream token.TokenStream) token.Token {
	result, err := token.NewGroup(delimiter, stream, ctx.DefSite())
	if err != nil {
		panic(err)
	}
	return result
}
func serdeSplice(ctx pm.Context, stream token.TokenStream, bindings map[string]token.TokenStream) token.TokenStream {
	result := token.New()
	for _, node := range stream.Tokens() {
		if value, ok := bindings[node.Text()]; ok && node.Kind() == token.IdentKind {
			result = result.Append(value.Tokens()...)
			continue
		}
		if node.Kind() == token.GroupKind {
			node = serdeGroup(ctx, node.Delimiter(), serdeSplice(ctx, node.Children(), bindings))
		}
		result = result.Append(node)
	}
	return result
}

type serdeField struct {
	wire         string
	renamed      bool
	defaultValue bool
	skip         bool
	deny         bool
	number       *int64
}

func serdeOptions(attributes []syn.Attribute, name, allowed string) (serdeField, error) {
	options := serdeField{wire: name}
	seen := map[string]bool{}
	for _, attribute := range attributes {
		path := attribute.Path().Tokens()
		if len(path) != 1 || path[0].Text() != "serde" {
			continue
		}
		arguments := attribute.Arguments().Tokens()
		if len(arguments) != 1 || arguments[0].Kind() != token.GroupKind || arguments[0].Delimiter() != token.Parenthesis {
			return options, fmt.Errorf("invalid serde attribute")
		}
		parts := arguments[0].Children().Tokens()
		if len(parts) == 0 {
			return options, fmt.Errorf("serde requires an attribute argument")
		}
		for index := 0; index < len(parts); {
			option := parts[index].Text()
			index++
			if !strings.Contains(" "+allowed+" ", " "+option+" ") {
				return options, fmt.Errorf("serde %s is not supported at this position", option)
			}
			if seen[option] {
				return options, fmt.Errorf("duplicate serde %s attribute", option)
			}
			seen[option] = true
			switch option {
			case "default":
				options.defaultValue = true
			case "skip":
				options.skip = true
			case "deny_unknown_fields":
				options.deny = true
			case "rename", "value":
				if index+1 >= len(parts) || parts[index].Text() != "=" {
					return options, fmt.Errorf("serde %s requires a literal value", option)
				}
				index++
				literal := parts[index].Text()
				index++
				if option == "rename" {
					var err error
					options.wire, err = strconv.Unquote(literal)
					if err != nil || !strings.HasPrefix(literal, "\"") && !strings.HasPrefix(literal, "`") {
						return options, fmt.Errorf("serde rename requires a string literal")
					}
					options.renamed = true
				} else {
					if literal == "-" && index < len(parts) {
						literal += parts[index].Text()
						index++
					}
					number, err := strconv.ParseInt(literal, 10, 64)
					if err != nil {
						return options, fmt.Errorf("serde value requires a signed int64 decimal literal")
					}
					options.number = &number
				}
			}
			if index < len(parts) {
				if parts[index].Text() != "," {
					return options, fmt.Errorf("serde attribute arguments must be comma-separated")
				}
				index++
			}
		}
	}
	return options, nil
}

func itemTarget(ctx pm.Context, item syn.Item) token.TokenStream {
	// A declaration name can originate in a declarative ident fragment. Refer
	// to the declared type with its binding context, not that opaque fragment.
	name := item.Name()
	identifier, err := token.NewIdent(name.Text(), name.Raw(), name.Context())
	if err != nil {
		panic(err)
	}
	target := token.New(identifier.WithSpan(name.Span()))
	parameters := item.Generics().Tokens()
	if len(parameters) == 0 {
		return target
	}
	var names []token.Token
	first := true
	for _, node := range parameters[0].Children().Tokens() {
		if node.Kind() == token.PunctKind && node.Text() == "," {
			first = true
			continue
		}
		if !first || node.Text() == "const" {
			continue
		}
		if len(names) != 0 {
			names = append(names, serdeFragment(ctx, ",").Tokens()...)
		}
		names = append(names, node)
		first = false
	}
	return target.Append(serdeGroup(ctx, token.Bracket, token.New(names...)))
}
func deriveSerde(ctx pm.Context, input token.TokenStream, write bool) pm.Output {
	item, err := syn.Parse(input)
	if err != nil {
		return pm.Failure(err.Error(), ctx.CallSpan())
	}
	if item.Alias() {
		return pm.Failure("serde derives require a defined struct or enum declaration", item.Span())
	}
	root, err := ctx.RuntimeRoot("github.com/goxide-lang/serde")
	if err != nil {
		return pm.Failure(err.Error(), ctx.CallSpan())
	}
	bindings := map[string]token.TokenStream{"__runtime": root, "__generics": item.Generics(), "__target": itemTarget(ctx, item)}
	protocol := "Deserialize"
	if write {
		protocol = "Serialize"
	}
	var body strings.Builder
	bounds := []string{}
	fields, record := item.Type().StructFields()
	if record {
		container, err := serdeOptions(item.Attributes(), "", "deny_unknown_fields")
		if err != nil {
			return pm.Failure(err.Error(), item.Span())
		}
		names, wires, types := []string{}, []string{}, []string{}
		options := []serdeField{}
		seen := map[string]bool{}
		for _, field := range fields {
			if len(field.Names()) == 0 {
				return pm.Failure("embedded fields are not supported", field.Span())
			}
			for _, name := range field.Names() {
				if name.Text() == "_" {
					return pm.Failure("blank fields are not supported", field.Span())
				}
				option, err := serdeOptions(field.Attributes(), name.Text(), "rename default skip")
				if err != nil {
					return pm.Failure(err.Error(), field.Span())
				}
				if seen[option.wire] {
					return pm.Failure("duplicate serde field name "+strconv.Quote(option.wire), field.Span())
				}
				seen[option.wire] = true
				n := len(names)
				fieldName, fieldType := fmt.Sprintf("__field%d", n), fmt.Sprintf("__type%d", n)
				names = append(names, fieldName)
				types = append(types, fieldType)
				wires = append(wires, strconv.Quote(option.wire))
				options = append(options, option)
				bindings[fieldName], bindings[fieldType] = name.ToTokens(), field.Type().ToTokens()
				if !option.skip {
					bounds = append(bounds, fieldType+":__runtime::"+protocol)
				}
				if !write && (option.defaultValue || option.skip) {
					standard, err := ctx.RuntimeRoot("github.com/goxide-lang/std")
					if err != nil {
						return pm.Failure(err.Error(), field.Span())
					}
					bindings["__standard"] = standard
					bounds = append(bounds, fieldType+":__standard::Default")
				}
			}
		}
		var activeWires []string
		for i, wire := range wires {
			if !options[i].skip {
				activeWires = append(activeWires, wire)
			}
		}
		if write {
			fmt.Fprintf(&body, "func serialize(self &Self,serializer __runtime::Serializer)error { writer,err:=serializer.Struct(%q,%d);if err!=nil{return err};", item.Name().Text(), len(activeWires))
			for i, name := range names {
				if options[i].skip {
					continue
				}
				fmt.Fprintf(&body, "if err:=writer.Field(%s,func(child __runtime::Serializer)error{return __runtime::Write(child,&self.%s)});err!=nil{return err};", wires[i], name)
			}
			body.WriteString("return writer.End() }")
		} else {
			body.WriteString("func deserialize(deserializer __runtime::Deserializer)(Self,error){var result Self;")
			for i := range names {
				if !options[i].skip {
					fmt.Fprintf(&body, "seen%d:=false;", i)
				}
			}
			fmt.Fprintf(&body, "err:=deserializer.Struct(%q,[]string{%s},__runtime::VisitorFuncs{OnMap:func(fields __runtime::MapAccess)error{for{var name string;more,err:=fields.NextKey(func(child __runtime::Deserializer)error{value,err:=__runtime::ReadString(child);name=value;return err});if err!=nil{return err};if !more{break};switch name{", item.Name().Text(), strings.Join(activeWires, ","))
			for i, name := range names {
				if options[i].skip {
					fmt.Fprintf(&body, "case %s:if err:=fields.NextValue(func(child __runtime::Deserializer)error{return child.Skip()});err!=nil{return err};", wires[i])
					continue
				}
				fmt.Fprintf(&body, "case %s:if seen%d{return __runtime::AtField(__runtime::NewError(__runtime::DuplicateField,\"duplicate field\"),name)};seen%d=true;if err:=fields.NextValue(func(child __runtime::Deserializer)error{value,err:=__runtime::Read[%s](child);result.%s=value;return err});err!=nil{return err};", wires[i], i, i, types[i], name)
			}
			if container.deny {
				body.WriteString("default:return __runtime::AtField(__runtime::NewError(__runtime::UnknownField,\"unknown field\"),name)")
			} else {
				body.WriteString("default:if err:=fields.NextValue(func(child __runtime::Deserializer)error{return child.Skip()});err!=nil{return err}")
			}
			body.WriteString("}};return nil}});if err!=nil{return result,err};")
			for i, name := range names {
				if options[i].skip || options[i].defaultValue {
					continue
				}
				fmt.Fprintf(&body, "if !seen%d{value,optional:=__runtime::Missing[%s]();if !optional{return result,__runtime::AtField(__runtime::NewError(__runtime::MissingField,\"required field missing\"),%s)};result.%s=value};", i, types[i], wires[i], name)
			}
			// Validate every required field before any business default runs.
			for i, name := range names {
				if options[i].skip {
					fmt.Fprintf(&body, "result.%s=__standard::default_value[%s]();", name, types[i])
				} else if options[i].defaultValue {
					fmt.Fprintf(&body, "if !seen%d{result.%s=__standard::default_value[%s]()};", i, name, types[i])
				}
			}
			body.WriteString("return result,nil};func missing()(Self,bool){var zero Self;return zero,false}")
		}
	} else if item.Kind() == syn.EnumItem {
		if _, err := serdeOptions(item.Attributes(), "", ""); err != nil {
			return pm.Failure(err.Error(), item.Span())
		}
		variants := item.Variants()
		wires, patterns, constructors := []string{}, []string{}, []string{}
		options := []serdeField{}
		payloads := []bool{}
		numeric, mapped := false, false
		for i, variant := range variants {
			name := fmt.Sprintf("__variant%d", i)
			bindings[name] = variant.Name().ToTokens()
			option, err := serdeOptions(variant.Attributes(), variant.Name().Text(), "rename value")
			if err != nil {
				return pm.Failure(err.Error(), variant.Span())
			}
			options = append(options, option)
			numeric = numeric || option.number != nil
			mapped = mapped || option.number != nil || option.renamed
			wires = append(wires, strconv.Quote(option.wire))
			fields := variant.Fields()
			count := 0
			for _, field := range fields {
				if _, err := serdeOptions(field.Attributes(), "", ""); err != nil {
					return pm.Failure("invalid attribute position: "+err.Error(), field.Span())
				}
				if variant.Kind() == syn.TupleVariant {
					count++
				} else {
					count += len(field.Names())
				}
			}
			if count > 1 {
				return pm.Failure("serde enum variant "+variant.Name().Text()+" requires a unit or single payload", variant.Span())
			}
			payloads = append(payloads, count != 0)
			path := fmt.Sprintf("__target::__variant%d", i)
			pattern, constructor := path, path
			if count == 1 {
				typ := fmt.Sprintf("__payload%d", i)
				bindings[typ] = fields[0].Type().ToTokens()
				bounds = append(bounds, typ+":__runtime::"+protocol)
				pattern, constructor = path+"(value)", path+"(value)"
				if variant.Kind() == syn.StructVariant {
					field := fields[0].Names()[0]
					if field.Text() == "_" {
						return pm.Failure("blank fields are not supported", field.Span())
					}
					key := fmt.Sprintf("__payloadName%d", i)
					bindings[key] = field.ToTokens()
					pattern, constructor = path+"{"+key+":value}", path+"{"+key+":value}"
				}
			}
			patterns, constructors = append(patterns, pattern), append(constructors, constructor)
		}
		seen := map[string]bool{}
		for i, variant := range variants {
			if mapped && payloads[i] {
				return pm.Failure("explicit enum serde mapping requires unit variants", variant.Span())
			}
			if numeric {
				if options[i].number == nil || options[i].renamed {
					return pm.Failure("numeric enum serde mapping requires value on every variant and cannot mix rename", variant.Span())
				}
				wires[i] = strconv.FormatInt(*options[i].number, 10)
			}
			if seen[wires[i]] {
				return pm.Failure("duplicate enum serde mapping "+wires[i], variant.Span())
			}
			seen[wires[i]] = true
		}
		if write {
			body.WriteString("func serialize(self &Self,serializer __runtime::Serializer)error{")
			if len(variants) == 0 {
				body.WriteString("return __runtime::NewError(__runtime::Type,\"invalid empty enum\")}")
			} else {
				body.WriteString("if !enum_valid(*self){return __runtime::NewError(__runtime::Type,\"invalid enum\")};return match &*self{")
				for i := range variants {
					if numeric {
						fmt.Fprintf(&body, "%s=>serializer.Int64(%s),", patterns[i], wires[i])
					} else if !payloads[i] {
						fmt.Fprintf(&body, "%s=>serializer.UnitVariant(%q,%s),", patterns[i], item.Name().Text(), wires[i])
					} else {
						fmt.Fprintf(&body, "%s=>serializer.NewtypeVariant(%q,%s,func(child __runtime::Serializer)error{return __runtime::Write(child,value)}),", patterns[i], item.Name().Text(), wires[i])
					}
				}
				body.WriteString("}}")
			}
		} else if numeric {
			body.WriteString("func deserialize(deserializer __runtime::Deserializer)(Self,error){var result Self;value,err:=__runtime::ReadInt64(deserializer);if err!=nil{return result,err};switch value{")
			for i := range variants {
				fmt.Fprintf(&body, "case %s:return %s,nil;", wires[i], constructors[i])
			}
			body.WriteString("default:return result,__runtime::NewError(__runtime::UnknownVariant,\"unknown numeric variant\")}};func missing()(Self,bool){var zero Self;return zero,false}")
		} else {
			accessName := "variant"
			if len(variants) == 0 {
				accessName = "_"
			}
			fmt.Fprintf(&body, "func deserialize(deserializer __runtime::Deserializer)(Self,error){var result Self;err:=deserializer.Enum(%q,[]string{%s},__runtime::VisitorFuncs{OnEnum:func(access __runtime::EnumAccess)error{name,%s,err:=access.Variant();if err!=nil{return err};switch name{", item.Name().Text(), strings.Join(wires, ","), accessName)
			for i := range variants {
				if !payloads[i] {
					fmt.Fprintf(&body, "case %s:if err:=variant.Unit();err!=nil{return err};result=%s;return nil;", wires[i], constructors[i])
				} else {
					fmt.Fprintf(&body, "case %s:return variant.Newtype(func(child __runtime::Deserializer)error{value,err:=__runtime::Read[__payload%d](child);if err!=nil{return err};result=%s;return nil});", wires[i], i, constructors[i])
				}
			}
			body.WriteString("default:return __runtime::NewError(__runtime::UnknownVariant,name)}}});return result,err};func missing()(Self,bool){var zero Self;return zero,false}")
		}
	} else {
		return pm.Failure("serde derives require defined structs and enums", item.Span())
	}
	where := ""
	// Concrete implementations prove field protocols in their ordinary bodies.
	// Making them prerequisites would introduce a spurious cycle for Node ->
	// *Node (and mutually recursive records) instead of ordinary recursion.
	if item.Generics().IsEmpty() {
		bounds = nil
	}
	if len(bounds) > 0 {
		where = "where " + strings.Join(bounds, ",")
	}
	if !item.Where().IsEmpty() {
		bindings["__where"] = item.Where()
		where = "__where"
		if len(bounds) != 0 {
			where += "," + strings.Join(bounds, ",")
		}
	}
	source := "impl __generics __runtime::" + protocol + " for __target " + where + " {" + body.String() + "};"
	return pm.Success(serdeSplice(ctx, serdeFragment(ctx, source), bindings))
}

// Package formatting supplies concrete formatter implementations and checked
// stdout writes for the finite print!/println! frontend protocol.
package formatting

import (
	"fmt"
	"io"
	"os"
	"strconv"
)

type WriteError struct {
	Written, Wanted int
	Cause           error
}

func (e *WriteError) Error() string {
	return fmt.Sprintf("goxide print: wrote %d of %d bytes: %v", e.Written, e.Wanted, e.Cause)
}
func (e *WriteError) Unwrap() error { return e.Cause }

// Write resolves stdout at execution time. Empty print performs no write.
func Write(text string) { WriteTo(os.Stdout, text) }

// WriteTo makes one write without retry or rollback, retaining the original
// error (or io.ErrShortWrite) and the observed partial byte count in its panic.
func WriteTo(w io.Writer, text string) {
	if text == "" {
		return
	}
	n, err := io.WriteString(w, text)
	if err == nil && n != len(text) {
		err = io.ErrShortWrite
	}
	if err != nil {
		panic(&WriteError{Written: n, Wanted: len(text), Cause: err})
	}
}
func DisplayString(v string) string  { return v }
func DebugString(v string) string    { return strconv.Quote(v) }
func Bool(v bool) string             { return strconv.FormatBool(v) }
func Int(v int) string               { return strconv.FormatInt(int64(v), 10) }
func Int8(v int8) string             { return strconv.FormatInt(int64(v), 10) }
func Int16(v int16) string           { return strconv.FormatInt(int64(v), 10) }
func Int32(v int32) string           { return strconv.FormatInt(int64(v), 10) }
func Int64(v int64) string           { return strconv.FormatInt(v, 10) }
func Uint(v uint) string             { return strconv.FormatUint(uint64(v), 10) }
func Uint8(v uint8) string           { return strconv.FormatUint(uint64(v), 10) }
func Uint16(v uint16) string         { return strconv.FormatUint(uint64(v), 10) }
func Uint32(v uint32) string         { return strconv.FormatUint(uint64(v), 10) }
func Uint64(v uint64) string         { return strconv.FormatUint(v, 10) }
func Uintptr(v uintptr) string       { return strconv.FormatUint(uint64(v), 10) }
func Float32(v float32) string       { return strconv.FormatFloat(float64(v), 'g', -1, 32) }
func Float64(v float64) string       { return strconv.FormatFloat(v, 'g', -1, 64) }
func Complex64(v complex64) string   { return strconv.FormatComplex(complex128(v), 'g', -1, 64) }
func Complex128(v complex128) string { return strconv.FormatComplex(v, 'g', -1, 128) }

package std_macros

import (
	"fmt"
	"strconv"

	pm "github.com/goxide-lang/syntax/proc_macro"
	"github.com/goxide-lang/syntax/syn"
	"github.com/goxide-lang/syntax/token"
)

func fragment(ctx pm.Context, source string) token.TokenStream {
	stream, err := token.ParseText(source, ctx.DefSite())
	if err != nil {
		panic(err)
	}
	nodes := stream.Tokens()
	for len(nodes) != 0 && nodes[len(nodes)-1].Kind() == token.SemicolonKind {
		nodes = nodes[:len(nodes)-1]
	}
	return token.New(nodes...)
}
func group(ctx pm.Context, delimiter token.Delimiter, body token.TokenStream) token.Token {
	value, err := token.NewGroup(delimiter, body, ctx.DefSite())
	if err != nil {
		panic(err)
	}
	return value
}
func derive(ctx pm.Context, input token.TokenStream, kind string) pm.Output {
	item, err := syn.Parse(input)
	if err != nil {
		return pm.Failure(err.Error(), ctx.CallSpan())
	}
	fields, ok := item.Type().StructFields()
	if kind == "Default" {
		misplaced := func(attrs []syn.Attribute) *syn.Attribute {
			for _, attr := range attrs {
				if errorAttribute(attr, "default") {
					return &attr
				}
			}
			return nil
		}
		if attr := misplaced(item.Attributes()); attr != nil {
			return pm.Failure("default belongs to an enum variant", attr.Span())
		}
		for _, field := range fields {
			if attr := misplaced(field.Attributes()); attr != nil {
				return pm.Failure("default belongs to an enum variant", attr.Span())
			}
		}
		for _, variant := range item.Variants() {
			for _, field := range variant.Fields() {
				if attr := misplaced(field.Attributes()); attr != nil {
					return pm.Failure("default belongs to an enum variant", attr.Span())
				}
			}
		}
	}
	if !ok && item.Kind() != syn.EnumItem && !item.Alias() && (kind == "PartialEq" || kind == "Eq" || kind == "NativeKey") {
		return deriveUnderlyingEquality(ctx, item, kind)
	}
	if (!ok && item.Kind() != syn.EnumItem) || item.Alias() {
		return pm.Failure("derive requires a defined struct or enum", item.Span())
	}
	root, err := ctx.RuntimeRoot("github.com/goxide-lang/std")
	if err != nil {
		return pm.Failure(err.Error(), ctx.CallSpan())
	}
	protocol := root.Append(fragment(ctx, "::"+kind).Tokens()...)
	if item.Kind() == syn.EnumItem {
		return deriveEnum(ctx, item, root, protocol, kind)
	}
	var predicates, values, body token.TokenStream
	if kind == "Debug" {
		body = fragment(ctx, "return "+strconv.Quote(item.Name().Text()+" {"))
	}
	count := 0
	for _, field := range fields {
		if len(field.Names()) == 0 {
			return pm.Failure("named fields required", field.Span())
		}
		if !predicates.IsEmpty() {
			predicates = predicates.Append(fragment(ctx, ",").Tokens()...)
		}
		predicates = predicates.Append(field.Type().ToTokens().Tokens()...).Append(fragment(ctx, ":").Tokens()...).Append(protocol.Tokens()...)
		for _, name := range field.Names() {
			if name.Text() == "_" {
				return pm.Failure("nonblank fields required", name.Span())
			}
			var call token.TokenStream
			if kind == "Default" {
				call = root.Append(fragment(ctx, "::default_value").Tokens()...).Append(group(ctx, token.Bracket, field.Type().ToTokens()), group(ctx, token.Parenthesis, token.New()))
			} else if kind == "Clone" || kind == "Debug" {
				member := "clone"
				if kind == "Debug" {
					member = "debug"
				}
				arg := fragment(ctx, "&self.").Append(name.ToTokens().Tokens()...)
				call = protocol.Append(fragment(ctx, "::"+member).Tokens()...).Append(group(ctx, token.Parenthesis, arg))
			} else if kind == "PartialEq" {
				args := fragment(ctx, "self.").Append(name.ToTokens().Tokens()...).Append(fragment(ctx, ",other.").Tokens()...).Append(name.ToTokens().Tokens()...)
				call = protocol.Append(fragment(ctx, "::equals").Tokens()...).Append(group(ctx, token.Parenthesis, args))
			}
			switch kind {
			case "Default", "Clone":
				values = values.Append(name.ToTokens().Tokens()...).Append(fragment(ctx, ":").Tokens()...).Append(call.Tokens()...).Append(fragment(ctx, ",").Tokens()...)
			case "Debug":
				label := " " + name.Text() + ": "
				if count != 0 {
					label = ", " + name.Text() + ": "
				}
				body = body.Append(fragment(ctx, "+"+strconv.Quote(label)+"+").Tokens()...).Append(call.Tokens()...)
			case "PartialEq":
				if count == 0 {
					body = fragment(ctx, "return")
				} else {
					body = body.Append(fragment(ctx, "&&").Tokens()...)
				}
				body = body.Append(call.Tokens()...)
			}
			count++
		}
	}
	var members token.TokenStream
	switch kind {
	case "Default", "Clone":
		signature := "func r#default() Self"
		if kind == "Clone" {
			signature = "func clone(self &Self) Self"
		}
		body = fragment(ctx, "return Self").Append(group(ctx, token.Brace, values))
		members = fragment(ctx, signature).Append(group(ctx, token.Brace, body))
	case "Debug":
		body = body.Append(fragment(ctx, "+\" }\"").Tokens()...)
		members = fragment(ctx, "func debug(self &Self) string").Append(group(ctx, token.Brace, body))
	case "PartialEq":
		if count == 0 {
			body = fragment(ctx, "return true")
		}
		members = fragment(ctx, "func equals(self Self,other Self) bool").Append(group(ctx, token.Brace, body))
	case "Eq", "NativeKey":
		// Eq is an ordinary marker constrained by its field protocols.
	}
	if kind == "Eq" {
		predicates = addPredicate(ctx, predicates, itemTarget(ctx, item), root.Append(fragment(ctx, "::DerivedPartialEq").Tokens()...))
	}
	output := implHeader(ctx, item, protocol)
	output = appendWhere(ctx, item, output, predicates)
	return finishDerive(ctx, item, root, output.Append(group(ctx, token.Brace, members)), predicates, kind)
}

// Enum generation reads each actual variant and field. Only Default's selected
// variant contributes prerequisites; Clone and Debug check every variant.
func deriveEnum(ctx pm.Context, item syn.Item, root, protocol token.TokenStream, kind string) pm.Output {
	if kind == "NativeKey" {
		return pm.Failure("NativeKey cannot be derived for an enum", item.Span())
	}
	if kind == "PartialEq" || kind == "Eq" {
		return deriveEnumEquality(ctx, item, root, protocol, kind)
	}
	variants := item.Variants()
	if kind == "Default" {
		var selected []syn.Variant
		for _, variant := range variants {
			for _, attr := range variant.Attributes() {
				path := attr.Path().Tokens()
				if len(path) != 1 || path[0].Text() != "default" {
					continue
				}
				arguments := attr.Arguments().Tokens()
				if len(arguments) != 0 && !(len(arguments) == 1 && arguments[0].Kind() == token.GroupKind && arguments[0].Delimiter() == token.Parenthesis && arguments[0].Children().IsEmpty()) {
					return pm.Failure("default takes no arguments", attr.Span())
				}
				selected = append(selected, variant)
			}
		}
		if len(selected) != 1 {
			return pm.Failure("Default requires exactly one default variant", item.Span())
		}
		variants = selected
	}
	var predicates, arms, body token.TokenStream
	for _, variant := range variants {
		var fieldTypes []token.TokenStream
		var fieldNames []syn.Ident
		for _, field := range variant.Fields() {
			if !predicates.IsEmpty() {
				predicates = predicates.Append(fragment(ctx, ",").Tokens()...)
			}
			predicates = predicates.Append(field.Type().ToTokens().Tokens()...).Append(fragment(ctx, ":").Tokens()...).Append(protocol.Tokens()...)
			if variant.Kind() == syn.TupleVariant {
				fieldTypes = append(fieldTypes, field.Type().ToTokens())
				fieldNames = append(fieldNames, syn.Ident{})
			} else {
				if len(field.Names()) == 0 {
					return pm.Failure("named enum fields required", field.Span())
				}
				for _, name := range field.Names() {
					if name.Text() == "_" {
						return pm.Failure("nonblank enum fields required", name.Span())
					}
					fieldTypes = append(fieldTypes, field.Type().ToTokens())
					fieldNames = append(fieldNames, name)
				}
			}
		}
		path := itemTarget(ctx, item).Append(fragment(ctx, "::").Tokens()...).Append(variant.Name().ToTokens().Tokens()...)
		var bindings, values token.TokenStream
		expression := fragment(ctx, strconv.Quote(item.Name().Text()+"::"+variant.Name().Text()))
		if kind == "Debug" && len(fieldTypes) > 0 {
			opening := "("
			if variant.Kind() == syn.StructVariant {
				opening = " { "
			}
			expression = expression.Append(fragment(ctx, "+"+strconv.Quote(opening)).Tokens()...)
		}
		for i, fieldType := range fieldTypes {
			if i != 0 {
				bindings = bindings.Append(fragment(ctx, ",").Tokens()...)
				values = values.Append(fragment(ctx, ",").Tokens()...)
				if kind == "Debug" {
					expression = expression.Append(fragment(ctx, "+"+strconv.Quote(", ")).Tokens()...)
				}
			}
			if variant.Kind() == syn.StructVariant {
				key := fieldNames[i].ToTokens().Append(fragment(ctx, ":").Tokens()...)
				bindings = bindings.Append(key.Tokens()...)
				values = values.Append(key.Tokens()...)
				if kind == "Debug" {
					expression = expression.Append(fragment(ctx, "+"+strconv.Quote(fieldNames[i].Text()+": ")).Tokens()...)
				}
			}
			binding := fragment(ctx, fmt.Sprintf("variantField%d", i))
			bindings = bindings.Append(binding.Tokens()...)
			var call token.TokenStream
			if kind == "Default" {
				call = root.Append(fragment(ctx, "::default_value").Tokens()...).Append(group(ctx, token.Bracket, fieldType), group(ctx, token.Parenthesis, token.New()))
			} else {
				member := "clone"
				if kind == "Debug" {
					member = "debug"
				}
				call = protocol.Append(fragment(ctx, "::"+member).Tokens()...).Append(group(ctx, token.Parenthesis, binding))
			}
			values = values.Append(call.Tokens()...)
			if kind == "Debug" {
				expression = expression.Append(fragment(ctx, "+").Tokens()...).Append(call.Tokens()...)
			}
		}
		constructor, pattern := path, path
		switch variant.Kind() {
		case syn.TupleVariant:
			constructor = constructor.Append(group(ctx, token.Parenthesis, values))
			pattern = pattern.Append(group(ctx, token.Parenthesis, bindings))
		case syn.StructVariant:
			constructor = constructor.Append(group(ctx, token.Brace, values))
			pattern = pattern.Append(group(ctx, token.Brace, bindings))
		}
		if kind == "Default" {
			body = fragment(ctx, "return").Append(constructor.Tokens()...)
			continue
		}
		if kind == "Debug" && len(fieldTypes) > 0 {
			closing := ")"
			if variant.Kind() == syn.StructVariant {
				closing = " }"
			}
			expression = expression.Append(fragment(ctx, "+"+strconv.Quote(closing)).Tokens()...)
		}
		if kind == "Clone" {
			expression = constructor
		}
		arms = arms.Append(pattern.Tokens()...).Append(fragment(ctx, "=>").Tokens()...).Append(expression.Tokens()...).Append(fragment(ctx, ",").Tokens()...)
	}
	signature := "func r#default() Self"
	if kind != "Default" {
		signature = "func clone(self &Self) Self"
		if kind == "Debug" {
			signature = "func debug(self &Self) string"
		}
		body = fragment(ctx, "return match &*self").Append(group(ctx, token.Brace, arms))
	}
	members := fragment(ctx, signature).Append(group(ctx, token.Brace, body))
	output := implHeader(ctx, item, protocol)
	output = appendWhere(ctx, item, output, predicates)
	return finishDerive(ctx, item, root, output.Append(group(ctx, token.Brace, members)), predicates, kind)
}

package std_macros

import (
	"fmt"

	pm "github.com/goxide-lang/syntax/proc_macro"
	"github.com/goxide-lang/syntax/syn"
	"github.com/goxide-lang/syntax/token"
)

// Generic declarations are replayed unchanged. The target uses only parameter
// names, retaining each source identifier's binding and raw spelling.
func itemTarget(ctx pm.Context, item syn.Item) token.TokenStream {
	// A declaration name can originate in a macro_rules ident fragment. Refer to
	// its binding as an identifier here, rather than moving that opaque fragment
	// into a type slot. Field types and all other captured fragments stay intact.
	name := item.Name()
	identifier, err := token.NewIdent(name.Text(), name.Raw(), name.Context())
	if err != nil {
		panic(err)
	}
	result := token.New(identifier.WithSpan(name.Span()))
	parameters := item.Generics().Tokens()
	if len(parameters) == 0 {
		return result
	}
	var names []token.Token
	first := true
	for _, node := range parameters[0].Children().Tokens() {
		if node.Kind() == token.PunctKind && node.Text() == "," {
			first = true
			continue
		}
		if !first || node.Text() == "const" {
			continue
		}
		if len(names) > 0 {
			names = append(names, fragment(ctx, ",").Tokens()...)
		}
		names = append(names, node)
		first = false
	}
	return result.Append(group(ctx, token.Bracket, token.New(names...)))
}

func implHeader(ctx pm.Context, item syn.Item, protocol token.TokenStream) token.TokenStream {
	return fragment(ctx, "impl").Append(item.Generics().Tokens()...).Append(protocol.Tokens()...).Append(fragment(ctx, "for").Tokens()...).Append(itemTarget(ctx, item).Tokens()...)
}

func appendWhere(ctx pm.Context, item syn.Item, output, predicates token.TokenStream) token.TokenStream {
	where := item.Where()
	if !where.IsEmpty() {
		output = output.Append(where.Tokens()...)
		if !predicates.IsEmpty() {
			output = output.Append(fragment(ctx, ",").Tokens()...)
		}
	} else if !predicates.IsEmpty() {
		output = output.Append(fragment(ctx, "where").Tokens()...)
	}
	return output.Append(predicates.Tokens()...)
}

func addPredicate(ctx pm.Context, predicates, typ, protocol token.TokenStream) token.TokenStream {
	if !predicates.IsEmpty() {
		predicates = predicates.Append(fragment(ctx, ",").Tokens()...)
	}
	return predicates.Append(typ.Tokens()...).Append(fragment(ctx, ":").Tokens()...).Append(protocol.Tokens()...)
}

func deriveUnderlyingEquality(ctx pm.Context, item syn.Item, kind string) pm.Output {
	root, err := ctx.RuntimeRoot("github.com/goxide-lang/std")
	if err != nil {
		return pm.Failure(err.Error(), ctx.CallSpan())
	}
	protocol := root.Append(fragment(ctx, "::"+kind).Tokens()...)
	predicates := addPredicate(ctx, token.New(), item.Type().ToTokens(), protocol)
	var members token.TokenStream
	if kind == "PartialEq" {
		underlying := token.New(group(ctx, token.Parenthesis, item.Type().ToTokens()))
		left := underlying.Append(group(ctx, token.Parenthesis, fragment(ctx, "self")))
		right := underlying.Append(group(ctx, token.Parenthesis, fragment(ctx, "other")))
		args := left.Append(fragment(ctx, ",").Tokens()...).Append(right.Tokens()...)
		call := protocol.Append(fragment(ctx, "::equals").Tokens()...).Append(group(ctx, token.Parenthesis, args))
		members = fragment(ctx, "func equals(self Self,other Self) bool").Append(group(ctx, token.Brace, fragment(ctx, "return").Append(call.Tokens()...)))
	}
	if kind == "Eq" {
		predicates = addPredicate(ctx, predicates, itemTarget(ctx, item), root.Append(fragment(ctx, "::DerivedPartialEq").Tokens()...))
	}
	output := appendWhere(ctx, item, implHeader(ctx, item, protocol), predicates)
	return finishDerive(ctx, item, root, output.Append(group(ctx, token.Brace, members)), predicates, kind)
}

func variantPattern(ctx pm.Context, item syn.Item, variant syn.Variant, prefix string) (token.TokenStream, []token.TokenStream) {
	path := itemTarget(ctx, item).Append(fragment(ctx, "::").Tokens()...).Append(variant.Name().ToTokens().Tokens()...)
	var bindings token.TokenStream
	var values []token.TokenStream
	for _, field := range variant.Fields() {
		names := field.Names()
		if variant.Kind() == syn.TupleVariant {
			names = []syn.Ident{{}}
		}
		for _, name := range names {
			if !bindings.IsEmpty() {
				bindings = bindings.Append(fragment(ctx, ",").Tokens()...)
			}
			if variant.Kind() == syn.StructVariant {
				bindings = bindings.Append(name.ToTokens().Tokens()...).Append(fragment(ctx, ":").Tokens()...)
			}
			value := fragment(ctx, fmt.Sprintf("%s%d", prefix, len(values)))
			bindings = bindings.Append(value.Tokens()...)
			values = append(values, value)
		}
	}
	switch variant.Kind() {
	case syn.TupleVariant:
		path = path.Append(group(ctx, token.Parenthesis, bindings))
	case syn.StructVariant:
		path = path.Append(group(ctx, token.Brace, bindings))
	}
	return path, values
}

func deriveEnumEquality(ctx pm.Context, item syn.Item, root, protocol token.TokenStream, kind string) pm.Output {
	if len(item.Variants()) == 0 {
		return pm.Failure("cannot derive equality for an empty enum", item.Span())
	}
	var predicates, arms, members token.TokenStream
	for _, variant := range item.Variants() {
		for _, field := range variant.Fields() {
			predicates = addPredicate(ctx, predicates, field.Type().ToTokens(), protocol)
		}
		if kind == "Eq" {
			continue
		}
		left, leftValues := variantPattern(ctx, item, variant, "enumLeft")
		right, rightValues := variantPattern(ctx, item, variant, "enumRight")
		comparison := fragment(ctx, "true")
		for i := range leftValues {
			args := leftValues[i].Append(fragment(ctx, ",").Tokens()...).Append(rightValues[i].Tokens()...)
			call := protocol.Append(fragment(ctx, "::equals").Tokens()...).Append(group(ctx, token.Parenthesis, args))
			if i == 0 {
				comparison = call
			} else {
				comparison = comparison.Append(fragment(ctx, "&&").Tokens()...).Append(call.Tokens()...)
			}
		}
		inner := right.Append(fragment(ctx, "=>").Tokens()...).Append(comparison.Tokens()...).Append(fragment(ctx, ",").Tokens()...)
		if len(item.Variants()) > 1 {
			inner = inner.Append(fragment(ctx, "_=>false,").Tokens()...)
		}
		expression := fragment(ctx, "match other").Append(group(ctx, token.Brace, inner))
		arms = arms.Append(left.Tokens()...).Append(fragment(ctx, "=>").Tokens()...).Append(expression.Tokens()...).Append(fragment(ctx, ",").Tokens()...)
	}
	if kind == "PartialEq" {
		// Evaluate both values before entering this method, then validate the
		// entire finite left payload before the right payload or user equality.
		body := fragment(ctx, "__goxide_enum_assert(self); __goxide_enum_assert(other); return match self").Append(group(ctx, token.Brace, arms))
		members = fragment(ctx, "func equals(self Self,other Self) bool").Append(group(ctx, token.Brace, body))
	}
	if kind == "Eq" {
		predicates = addPredicate(ctx, predicates, itemTarget(ctx, item), root.Append(fragment(ctx, "::DerivedPartialEq").Tokens()...))
	}
	output := appendWhere(ctx, item, implHeader(ctx, item, protocol), predicates)
	return finishDerive(ctx, item, root, output.Append(group(ctx, token.Brace, members)), predicates, kind)
}

func assertTokens(ctx pm.Context, input token.TokenStream) pm.Output {
	if input.IsEmpty() {
		return pm.Failure("enum_assert requires one value", ctx.CallSpan())
	}
	output := fragment(ctx, "__goxide_enum_assert").Append(group(ctx, token.Parenthesis, input))
	return pm.Success(output)
}

func finishDerive(ctx pm.Context, item syn.Item, root, output, predicates token.TokenStream, kind string) pm.Output {
	if kind == "PartialEq" {
		marker := root.Append(fragment(ctx, "::DerivedPartialEq").Tokens()...)
		declaration := appendWhere(ctx, item, implHeader(ctx, item, marker), predicates).Append(group(ctx, token.Brace, token.New()))
		output = output.Append(token.NewSemicolon(ctx.DefSite())).Append(declaration.Tokens()...)
	}
	return pm.Success(output)
}

package std_macros

import (
	"fmt"
	"strconv"
	"strings"

	pm "github.com/goxide-lang/syntax/proc_macro"
	"github.com/goxide-lang/syntax/syn"
	"github.com/goxide-lang/syntax/token"
)

func errorSplice(ctx pm.Context, stream token.TokenStream, bindings map[string]token.TokenStream) token.TokenStream {
	result := token.New()
	for _, node := range stream.Tokens() {
		if value, ok := bindings[node.Text()]; ok && node.Kind() == token.IdentKind {
			result = result.Append(value.Tokens()...)
			continue
		}
		if node.Kind() == token.GroupKind {
			var err error
			node, err = token.NewGroup(node.Delimiter(), errorSplice(ctx, node.Children(), bindings), ctx.DefSite())
			if err != nil {
				panic(err)
			}
		}
		result = result.Append(node)
	}
	return result
}

func errorAttribute(attribute syn.Attribute, name string) bool {
	path := attribute.Path().Tokens()
	return len(path) == 1 && path[0].Text() == name
}

func errorMessage(message string, fields map[string]string) (string, error) {
	var parts []string
	var literal strings.Builder
	flush := func() {
		if literal.Len() != 0 {
			parts = append(parts, strconv.Quote(literal.String()))
			literal.Reset()
		}
	}
	for i := 0; i < len(message); {
		if strings.HasPrefix(message[i:], "{{") || strings.HasPrefix(message[i:], "}}") {
			literal.WriteByte(message[i])
			i += 2
			continue
		}
		if message[i] == '}' {
			return "", fmt.Errorf("unmatched closing brace in error message")
		}
		if message[i] != '{' {
			literal.WriteByte(message[i])
			i++
			continue
		}
		flush()
		end := strings.IndexByte(message[i+1:], '}')
		if end < 0 {
			return "", fmt.Errorf("unclosed error placeholder")
		}
		end += i + 1
		name := message[i+1 : end]
		field, ok := fields[name]
		if !ok {
			return "", fmt.Errorf("unknown error placeholder %q", name)
		}
		// An exact ordinary Go type-set enforces the builtin-scalar boundary.
		// The macro neither examines resolved types nor recognizes aliases.
		parts = append(parts, "__runtime::error_scalar("+field+")")
		i = end + 1
	}
	flush()
	if len(parts) == 0 {
		return strconv.Quote(""), nil
	}
	return strings.Join(parts, "+"), nil
}

type errorAttributes struct {
	message                  string
	hasMessage, source, from bool
}

func readErrorAttributes(attrs []syn.Attribute) (errorAttributes, error) {
	var result errorAttributes
	seen := map[string]bool{}
	for _, attr := range attrs {
		name := ""
		for _, candidate := range []string{"error", "source", "from"} {
			if errorAttribute(attr, candidate) {
				name = candidate
			}
		}
		if name == "" {
			continue
		}
		if seen[name] {
			return result, fmt.Errorf("duplicate %s attribute", name)
		}
		seen[name] = true
		if name != "error" {
			if !attr.Arguments().IsEmpty() {
				return result, fmt.Errorf("%s attribute takes no arguments", name)
			}
			if name == "source" {
				result.source = true
			} else {
				result.from = true
			}
			continue
		}
		args := attr.Arguments().Tokens()
		if len(args) != 1 || args[0].Kind() != token.GroupKind || args[0].Delimiter() != token.Parenthesis {
			return result, fmt.Errorf("error requires one string literal")
		}
		text := args[0].Children().Tokens()
		if len(text) != 1 || text[0].Kind() != token.LiteralKind || text[0].LiteralType() != token.String {
			return result, fmt.Errorf("error requires one string literal")
		}
		value, err := strconv.Unquote(text[0].Text())
		if err != nil {
			return result, err
		}
		result.message, result.hasMessage = value, true
	}
	return result, nil
}

func deriveError(ctx pm.Context, input token.TokenStream) pm.Output {
	item, err := syn.Parse(input)
	if err != nil {
		return pm.Failure(err.Error(), ctx.CallSpan())
	}
	if item.Alias() {
		return pm.Failure("Error requires a defined struct or enum", item.Span())
	}
	root, err := ctx.RuntimeRoot("github.com/goxide-lang/std")
	if err != nil {
		return pm.Failure(err.Error(), ctx.CallSpan())
	}
	if item.Kind() == syn.EnumItem {
		return deriveEnumError(ctx, item, root)
	}
	fields, ok := item.Type().StructFields()
	if !ok {
		return pm.Failure("Error requires a defined struct or enum", item.Span())
	}
	attrs, err := readErrorAttributes(item.Attributes())
	if err != nil {
		return pm.Failure(err.Error(), item.Span())
	}
	if !attrs.hasMessage || attrs.source || attrs.from {
		return pm.Failure("Error struct requires a message; source/from belong to a field", item.Span())
	}
	bindings := map[string]token.TokenStream{"__runtime": root}
	names := map[string]string{}
	source, from := "", false
	for _, field := range fields {
		if len(field.Names()) == 0 {
			return pm.Failure("embedded fields have no Error derive protocol", field.Span())
		}
		attr, err := readErrorAttributes(field.Attributes())
		if err != nil {
			return pm.Failure(err.Error(), field.Span())
		}
		if attr.hasMessage {
			return pm.Failure("error message belongs to the struct, not a field", field.Span())
		}
		for _, name := range field.Names() {
			if name.Text() == "_" {
				return pm.Failure("blank fields have no Error derive protocol", name.Span())
			}
			key := fmt.Sprintf("__field%d", len(names))
			bindings[key] = name.ToTokens()
			names[name.Text()] = "self." + key
			if attr.source || attr.from {
				if source != "" {
					return pm.Failure("Error requires at most one source field", field.Span())
				}
				source, from = key, attr.from
			}
		}
	}
	if from && len(names) != 1 {
		return pm.Failure("from requires exactly one error field", item.Span())
	}
	message, err := errorMessage(attrs.message, names)
	if err != nil {
		return pm.Failure(err.Error(), item.Span())
	}
	members := "pub func Error(self Self)string{return " + message + "}"
	if source != "" {
		members += ";pub func Unwrap(self Self)error{return __runtime::error_source(&self." + source + ")}"
	}
	header := fragment(ctx, "impl").Append(item.Generics().Tokens()...).Append(itemTarget(ctx, item).Tokens()...).Append(item.Where().Tokens()...)
	output := header.Append(group(ctx, token.Brace, errorSplice(ctx, fragment(ctx, members), bindings)))
	if from {
		protocol := root.Append(fragment(ctx, "::From[error]").Tokens()...)
		constructor := fragment(ctx, "Self").Append(group(ctx, token.Brace, bindings[source].Append(fragment(ctx, ":value").Tokens()...)))
		body := fragment(ctx, "return").Append(constructor.Tokens()...)
		fromMembers := fragment(ctx, "func from(value error)Self").Append(group(ctx, token.Brace, body))
		output = output.Append(token.NewSemicolon(ctx.DefSite())).Append(implHeader(ctx, item, protocol).Append(item.Where().Tokens()...).Append(group(ctx, token.Brace, fromMembers)).Tokens()...)
	}
	return pm.Success(output)
}

func deriveEnumError(ctx pm.Context, item syn.Item, root token.TokenStream) pm.Output {
	attrs, err := readErrorAttributes(item.Attributes())
	if err != nil {
		return pm.Failure(err.Error(), item.Span())
	}
	if attrs.hasMessage || attrs.source || attrs.from {
		return pm.Failure("enum error/source/from attributes belong to variants", item.Span())
	}
	if len(item.Variants()) == 0 {
		return pm.Failure("Error requires a nonempty enum", item.Span())
	}
	var errorArms, sourceArms, fromMember token.TokenStream
	for _, variant := range item.Variants() {
		attr, err := readErrorAttributes(variant.Attributes())
		if err != nil {
			return pm.Failure(err.Error(), variant.Span())
		}
		if !attr.hasMessage {
			return pm.Failure("Error variant requires an error message", variant.Span())
		}
		pattern, values := variantPattern(ctx, item, variant, "errorField")
		if (attr.source || attr.from) && len(values) != 1 {
			return pm.Failure("source/from variant requires one error payload", variant.Span())
		}
		if attr.from && !fromMember.IsEmpty() {
			return pm.Failure("Error requires at most one from variant", variant.Span())
		}
		names := map[string]string{}
		bindings := map[string]token.TokenStream{"__runtime": root}
		index := 0
		for _, field := range variant.Fields() {
			fieldAttr, err := readErrorAttributes(field.Attributes())
			if err != nil {
				return pm.Failure(err.Error(), field.Span())
			}
			if fieldAttr.hasMessage || fieldAttr.source || fieldAttr.from {
				return pm.Failure("enum error/source/from attributes belong to variants", field.Span())
			}
			fieldNames := field.Names()
			if variant.Kind() == syn.TupleVariant {
				label := "Value"
				if len(values) > 1 {
					label = fmt.Sprintf("V%d", index)
				}
				key := fmt.Sprintf("__field%d", index)
				names[label] = key
				bindings[key] = values[index]
				index++
				continue
			}
			if len(fieldNames) == 0 {
				return pm.Failure("named enum fields required", field.Span())
			}
			for _, name := range fieldNames {
				if name.Text() == "_" {
					return pm.Failure("blank fields have no Error derive protocol", name.Span())
				}
				key := fmt.Sprintf("__field%d", index)
				names[name.Text()] = key
				bindings[key] = values[index]
				index++
			}
		}
		message, err := errorMessage(attr.message, names)
		if err != nil {
			return pm.Failure(err.Error(), variant.Span())
		}
		expression := errorSplice(ctx, fragment(ctx, message), bindings)
		errorArms = errorArms.Append(pattern.Tokens()...).Append(fragment(ctx, "=>").Tokens()...).Append(expression.Tokens()...).Append(fragment(ctx, ",").Tokens()...)
		source := fragment(ctx, "nil")
		if attr.source || attr.from {
			source = root.Append(fragment(ctx, "::error_source").Tokens()...).Append(group(ctx, token.Parenthesis, fragment(ctx, "&").Append(values[0].Tokens()...)))
		}
		sourceArms = sourceArms.Append(pattern.Tokens()...).Append(fragment(ctx, "=>").Tokens()...).Append(source.Tokens()...).Append(fragment(ctx, ",").Tokens()...)
		if attr.from {
			constructor := itemTarget(ctx, item).Append(fragment(ctx, "::").Tokens()...).Append(variant.Name().ToTokens().Tokens()...)
			if variant.Kind() == syn.TupleVariant {
				constructor = constructor.Append(group(ctx, token.Parenthesis, fragment(ctx, "value")))
			} else {
				constructor = constructor.Append(group(ctx, token.Brace, variant.Fields()[0].Names()[0].ToTokens().Append(fragment(ctx, ":value").Tokens()...)))
			}
			fromMember = fragment(ctx, "func from(value error)Self").Append(group(ctx, token.Brace, fragment(ctx, "return").Append(constructor.Tokens()...)))
		}
	}
	errorBody := fragment(ctx, "return match self").Append(group(ctx, token.Brace, errorArms))
	sourceBody := fragment(ctx, "return match self").Append(group(ctx, token.Brace, sourceArms))
	members := fragment(ctx, "pub func Error(self Self)string").Append(group(ctx, token.Brace, errorBody)).Append(fragment(ctx, ";pub func Unwrap(self Self)error").Tokens()...).Append(group(ctx, token.Brace, sourceBody))
	header := fragment(ctx, "impl").Append(item.Generics().Tokens()...).Append(itemTarget(ctx, item).Tokens()...).Append(item.Where().Tokens()...)
	output := header.Append(group(ctx, token.Brace, members))
	if !fromMember.IsEmpty() {
		protocol := root.Append(fragment(ctx, "::From[error]").Tokens()...)
		output = output.Append(token.NewSemicolon(ctx.DefSite())).Append(implHeader(ctx, item, protocol).Append(item.Where().Tokens()...).Append(group(ctx, token.Brace, fromMember)).Tokens()...)
	}
	return pm.Success(output)
}

package std_macros

import (
	"fmt"
	"strconv"
	"strings"

	pm "github.com/goxide-lang/syntax/proc_macro"
	"github.com/goxide-lang/syntax/token"
)

type part struct {
	literal     string
	slot, debug bool
}

func parts(source string) ([]part, error) {
	var result []part
	var literal strings.Builder
	flush := func() {
		if literal.Len() > 0 {
			result = append(result, part{literal: literal.String()})
			literal.Reset()
		}
	}
	for i := 0; i < len(source); {
		switch {
		case strings.HasPrefix(source[i:], "{{"), strings.HasPrefix(source[i:], "}}"):
			literal.WriteByte(source[i])
			i += 2
		case strings.HasPrefix(source[i:], "{}"):
			flush()
			result = append(result, part{slot: true})
			i += 2
		case strings.HasPrefix(source[i:], "{:?}"):
			flush()
			result = append(result, part{slot: true, debug: true})
			i += 4
		case source[i] == '{' || source[i] == '}':
			return nil, fmt.Errorf("unsupported or unmatched format brace")
		default:
			literal.WriteByte(source[i])
			i++
		}
	}
	flush()
	return result, nil
}
func printTokens(ctx pm.Context, input token.TokenStream, newline bool) pm.Output {
	fail := func(message string) pm.Output { return pm.Failure(message, ctx.CallSpan()) }
	var arguments []token.TokenStream
	var current []token.Token
	for _, node := range input.Tokens() {
		if node.Kind() == token.SemicolonKind {
			return fail("format arguments cannot contain top-level semicolons")
		}
		if node.Kind() == token.PunctKind && node.Text() == "..." {
			return fail("variadic print arguments are unsupported")
		}
		if node.Kind() == token.PunctKind && node.Text() == "," {
			if len(current) == 0 {
				return fail("empty format argument")
			}
			arguments = append(arguments, token.New(current...))
			current = nil
			continue
		}
		current = append(current, node)
	}
	if len(current) > 0 {
		arguments = append(arguments, token.New(current...))
	}
	format := ""
	if len(arguments) == 0 {
		if !newline {
			return fail("print requires a format string literal")
		}
	} else {
		tokens := arguments[0].Tokens()
		for len(tokens) == 1 && tokens[0].Kind() == token.FragmentKind {
			tokens = tokens[0].Children().Tokens()
		}
		if len(tokens) != 1 || tokens[0].Kind() != token.LiteralKind || tokens[0].LiteralType() != token.String {
			return fail("print format must be a string literal")
		}
		var err error
		format, err = strconv.Unquote(tokens[0].Text())
		if err != nil {
			return fail(err.Error())
		}
		arguments = arguments[1:]
	}
	plan, err := parts(format)
	if err != nil {
		return fail(err.Error())
	}
	count := 0
	for _, part := range plan {
		if part.slot {
			count++
		}
	}
	if count != len(arguments) {
		return fail(fmt.Sprintf("format has %d placeholders but %d arguments", count, len(arguments)))
	}
	root, err := ctx.RuntimeRoot("github.com/goxide-lang/std")
	if err != nil {
		return fail(err.Error())
	}
	// Declarations keep this output in statement slots, and evaluate every
	// argument before running any formatter. No closure changes ? or recover.
	output := fragment(ctx, "var printingText string").Append(token.NewSemicolon(ctx.DefSite()))
	for i, argument := range arguments {
		output = output.Append(fragment(ctx, fmt.Sprintf("var printingArgument%d =", i)).Tokens()...).Append(argument.Tokens()...).Append(token.NewSemicolon(ctx.DefSite()))
	}
	index := 0
	for _, part := range plan {
		output = output.Append(fragment(ctx, "printingText +=").Tokens()...)
		if !part.slot {
			output = output.Append(fragment(ctx, strconv.Quote(part.literal)).Tokens()...)
		} else {
			member := "Display::display"
			if part.debug {
				member = "Debug::debug"
			}
			call := root.Append(fragment(ctx, "::"+member).Tokens()...).Append(group(ctx, token.Parenthesis, fragment(ctx, fmt.Sprintf("&printingArgument%d", index))))
			output = output.Append(call.Tokens()...)
			index++
		}
		output = output.Append(token.NewSemicolon(ctx.DefSite()))
	}
	if newline {
		output = output.Append(fragment(ctx, "printingText += \"\\n\"").Tokens()...).Append(token.NewSemicolon(ctx.DefSite()))
	}
	output = output.Append(root.Tokens()...).Append(fragment(ctx, "::formatting::Write(printingText)").Tokens()...).Append(token.NewSemicolon(ctx.DefSite()))
	return pm.Success(output)
}

package goxideruntime

// Assignment is compiler support for an assignment whose hidden promoted
// pointer operands must be staged by Go itself. It is not a source protocol.
// Each statement owns a distinct guard and defers Catch in the source function,
// after all earlier source defers. Ordinary panics and Goexit are untouched.
type Assignment[T any] struct {
	pending bool
	result  T
	token   byte // Nonzero-sized storage gives each guard a distinct address.
}

// Fail is called only after validation and error conversion have completed.
// There are no user frames between this panic and the statement's Catch.
func (g *Assignment[T]) Fail(result T) {
	g.result = result
	g.pending = true
	panic(&g.token)
}

// Catch must itself be deferred by the source function, not called through a
// wrapper. Inactive guards do not even call recover, preserving ordinary panic,
// legacy panic(nil), and Goexit behavior.
func (g *Assignment[T]) Catch(result *T) {
	if !g.pending {
		return
	}
	if value := recover(); value != &g.token {
		panic(value)
	}
	*result = g.result
	g.pending = false
}

// Package goxideruntime provides compiler support for generated Go. These names
// are lowering details, not source-language protocols or a stable public ABI.
package goxideruntime

// Comparable preserves the Go constraint's identity when a source package
// declares its own identifier named comparable.
type Comparable interface{ comparable }

// Package sum provides shared value representations for Goxide Option and Result.
// Shape validation does not replace compiler-generated payload validation.
package sum

// GoxideSumABI identifies the representation contract, not a module release.
const GoxideSumABI = 3

// Tag names Go's int type for generated discriminants even when a source
// package declares its own int. It does not change the runtime representation.
type Tag = int

// Option has an independent inline Some slot. Its zero value is None.
// Assignment copies the slot with ordinary Go shallow-value semantics.
type Option[T any] struct {
	tag  uint8
	some T
}

// NewSome constructs Some without cloning or validating its payload.
func NewSome[T any](value T) Option[T] { return Option[T]{tag: 1, some: value} }

// None constructs an absent Option. Some with a nil payload remains present.
func None[T any]() Option[T] { return Option[T]{} }

// ValidateOption checks the tag, not inactive storage or payload invariants.
func ValidateOption[T any](value Option[T]) {
	if value.tag > 1 {
		panic("goxide: invalid enum Option")
	}
}

// TagOption reads the raw tag: 0 denotes None and 1 denotes Some.
// It does not replace ValidateOption.
func TagOption[T any](value Option[T]) int { return int(value.tag) }

// ValueSome copies the active payload using ordinary Go assignment.
func ValueSome[T any](value Option[T]) T {
	if TagOption(value) != 1 {
		panic("goxide: expected Option::Some")
	}
	return value.some
}

// ProjectSome returns the actual Some slot. The pointer remains attached to
// this storage even if the Option is later replaced with None or another Some.
// It is an ordinary Go pointer; no exclusivity or lifetime restriction is added.
func ProjectSome[T any](value *Option[T]) *T {
	if value == nil {
		panic("goxide: nil Option projection")
	}
	if TagOption(*value) != 1 {
		panic("goxide: expected Option::Some")
	}
	return &value.some
}

// Result has independent inline Ok and Err slots. Its zero value is invalid.
// Both type parameters participate in its nominal identity and storage.
type Result[T, E any] struct {
	tag uint8
	ok  T
	err E
}

// NewOk constructs Ok without cloning or validating its payload.
func NewOk[T, E any](value T) Result[T, E] { return Result[T, E]{tag: 1, ok: value} }

// NewErr constructs Err even when the payload is nil. Whether a native Go error
// indicates success belongs to the call adapter, not this constructor.
func NewErr[T, E any](value E) Result[T, E] { return Result[T, E]{tag: 2, err: value} }

// ValidateResult checks only the active tag. Inactive slots may contain values
// written through older projections; they are not part of the active variant.
func ValidateResult[T, E any](value Result[T, E]) {
	if value.tag != 1 && value.tag != 2 {
		panic("goxide: invalid enum Result")
	}
}

// TagResult reads the raw tag: 1 denotes Ok and 2 denotes Err; zero is invalid.
// It does not replace ValidateResult.
func TagResult[T, E any](value Result[T, E]) int { return int(value.tag) }

// ValueOk copies the active Ok payload.
func ValueOk[T, E any](value Result[T, E]) T {
	if TagResult(value) != 1 {
		panic("goxide: expected Result::Ok")
	}
	return value.ok
}

// ValueErr copies the active Err payload.
func ValueErr[T, E any](value Result[T, E]) E {
	if TagResult(value) != 2 {
		panic("goxide: expected Result::Err")
	}
	return value.err
}

// ProjectOk returns the actual Ok slot, with the same fixed-storage contract as ProjectSome.
func ProjectOk[T, E any](value *Result[T, E]) *T {
	if value == nil {
		panic("goxide: nil Result projection")
	}
	if TagResult(*value) != 1 {
		panic("goxide: expected Result::Ok")
	}
	return &value.ok
}

// ProjectErr returns a separate slot even when T and E are the same type.
func ProjectErr[T, E any](value *Result[T, E]) *E {
	if value == nil {
		panic("goxide: nil Result projection")
	}
	if TagResult(*value) != 2 {
		panic("goxide: expected Result::Err")
	}
	return &value.err
}

// Package typeinfo supplies the compile-time carrier constraint used by
// Goxide-generated Go. It does not discover types or call carrier methods.
package typeinfo

// GoxideTypeInfoABI identifies the carrier contract, not a module release.
const GoxideTypeInfoABI = 1

// CarrierFor associates T with a zero-field struct type S. The method's T
// parameter requires the exact self type: promoting a method from an embedded
// parent does not associate its child with the parent's carrier.
//
// This structural Go constraint does not establish compiler provenance. The
// compiler must separately validate any generated metadata it trusts.
type CarrierFor[T any, S ~struct{}] interface {
	GoxideInternalTypeCarrierForSelf(T) S
}

// Of returns the zero value of T's carrier type. It does not construct T, call
// its carrier method, or inspect a value at runtime.
func Of[T CarrierFor[T, S], S ~struct{}]() S {
	var zero S
	return zero
}

