package main

type User struct { Name string }

impl Build for User {
    func Abc() Self {
        return Self{Name: "Ada"}
    }
}

package main

// The same alias belongs to a different namespace in main.gox.
use strings as util;

func title() string { return util::ToUpper("goxide") }

package main

use fmt;
use strconv as util;
use serde::json as serdejson;
use serde;
use std;

func main() {
    item := Item{Value: 21}
    data, err := serdejson::Marshal(&item, serde::Write[Item])
    if err != nil { panic(err) }
    item, err = serdejson::Unmarshal(data, serde::Read[Item])
    if err != nil { panic(err) }
    copy := std::Clone::clone(&item)
    fmt::Println(util::Itoa(twice!(copy.Value)), title(), std::Debug::debug(&copy))
    direct := User::Abc()
    generic := Make[User]()
    fmt::Println(direct.Name, generic.Name)
}

package main

// Each file independently binds util to its declared namespace.
use serde as util;
use std;

#[derive(std::derive::Clone, std::derive::Debug, util::derive::Serialize, util::derive::Deserialize)]
type Item struct { Value int }

// Package declarations and macros are available to sibling files.
macro_rules! twice {
    ($value:expr) => {
        func() int { value := $value; return value + value }()
    };
}

package main

trait Build {
    func Abc() Self
}

func Make[T Build]() T {
    return T::Abc()
}

