package main

import "fmt"

type Status int

const (
	Pending Status = iota
	Paid
	Shipped
)

type Order struct {
	Status   Status
	Amount   int
	Tracking string
}

func Describe(id int, order Order) string {
	var status string
	switch order.Status {
	case Pending:
		status = "pending"
	case Paid:
		status = fmt.Sprintf("paid %d", order.Amount)
	case Shipped:
		status = "shipped " + order.Tracking
	default:
		panic("unknown order status")
	}
	return fmt.Sprintf("order %d: %s", id, status)
}

package main

import "testing"

func TestDescribe(t *testing.T) {
	cases := []struct {
		order Order
		want  string
	}{
		{Order{Status: Pending}, "order 7: pending"},
		{Order{Status: Paid, Amount: 42}, "order 7: paid 42"},
		{Order{Status: Shipped, Tracking: "TRACK-7"}, "order 7: shipped TRACK-7"},
	}
	for _, test := range cases {
		if got := Describe(7, test.order); got != test.want {
			t.Fatalf("Describe() = %q, want %q", got, test.want)
		}
	}
}

